"""Pin the published Chart.js build and emit a CSP-compatible serializable installer."""
from pathlib import Path
import argparse, hashlib, json, re

ROOT = Path(__file__).resolve().parents[1]
VERSION = '4.6.1'


def generate_installer(original, license, color_license):
    code=re.sub(r'\n?//# sourceMappingURL=[^\r\n]*','',original.decode()).rstrip()
    # No eval/Function/inline DOM script; this function is ordinary module code in the app.
    return (f'/** Chart.js {VERSION}, MIT. Generated by scripts/build-chart-vendor.py. */\n'
      f'export function installChartJs(){{if(globalThis.Chart?.version==={json.dumps(VERSION)})return globalThis.Chart;\n'
      '/* Chart.js license\n'+license.decode()+'\nBundled @kurkle/color license\n'+color_license.decode()+'\n*/\n'
      '{const module=undefined,exports=undefined,define=undefined;\n'+code+'\n}\nreturn globalThis.Chart;}\n').encode()


def bundled_installer(check):
    """Use only the distributed inputs; never rewrite supplier files or provenance."""
    bundled=ROOT/'assets/vendor/charts'
    manifest=json.loads((bundled/'provenance.json').read_text(encoding='utf8'))

    def require(condition, message):
        if not condition:
            raise ValueError(message)

    require(manifest.get('schemaVersion')==1 and manifest.get('package')=='chart.js'
            and manifest.get('version')==VERSION and manifest.get('license')=='MIT',
            'Bundled Chart.js provenance does not match the pinned MIT distribution')
    original=(bundled/'chart.umd.min.js').read_bytes()
    original_record=manifest.get('originalDist',{})
    require(original_record.get('path')=='assets/vendor/charts/chart.umd.min.js'
            and original_record.get('bytes')==len(original)
            and original_record.get('sha256')==hashlib.sha256(original).hexdigest(),
            'Bundled Chart.js bytes differ from the recorded original distribution')
    require(any(item.get('package')=='@kurkle/color' and item.get('version')=='0.3.2'
                and item.get('license')=='MIT'
                and item.get('licenseFile')=='assets/vendor/charts/KURKLE-COLOR-LICENSE.md'
                for item in manifest.get('bundledDependencies',[])),
            'Bundled @kurkle/color provenance is missing or incompatible')
    license=(bundled/'LICENSE.md').read_bytes()
    color_license=(bundled/'KURKLE-COLOR-LICENSE.md').read_bytes()
    generated=generate_installer(original,license,color_license)
    target=ROOT/'src/chart-vendor.js'
    if check:
        require(target.read_bytes()==generated,'src/chart-vendor.js differs from the bundled installer')
        generated_record=manifest.get('generatedModule',{})
        require(generated_record.get('path')=='src/chart-vendor.js'
                and generated_record.get('bytes')==len(generated)
                and generated_record.get('sha256')==hashlib.sha256(generated).hexdigest(),
                'Bundled installer differs from the recorded generated module')
    else:
        target.parent.mkdir(parents=True,exist_ok=True)
        target.write_bytes(generated)
    print(json.dumps({'checked':check,'bundled':True,'version':VERSION,
                      'originalBytes':len(original),'moduleBytes':len(generated)}))


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    parser.add_argument('--bundled',action='store_true',
                        help='Use only distributed assets/vendor/charts inputs; write only src/chart-vendor.js')
    args=parser.parse_args()
    bundled_installer(args.check)

if __name__=='__main__':main()
